test('vatSummary aggregates multiple invoices per rate', () => {
  // Invoice 1: LOGO-PACK (21% VAT)
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []).value;

  // Invoice 2: Another LOGO-PACK (21% VAT)
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2025-0001']).value;

  const result = vatSummary([issued1, issued2]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // Both invoices combined: 2 * 120000 = 240000, vat = 2 * 25200 = 50400
  assert.equal(result[0].base, 240000);
  assert.equal(result[0].vat, 50400);
});

test('vatSummary with mixed invoice statuses', () => {
  // Draft invoice (should be filtered out)
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  // Issued invoice
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, []).value;

  // Partially paid invoice
  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  let issued3 = issueInvoice(inv3.value, ['INV-2025-0001']).value;
  const totals3 = invoiceTotals(issued3);
  issued3 = recordPayment(issued3, {
    amount: Math.floor(totals3.total / 2),
    date: '2025-10-10',
  }).value;

  // Paid invoice
  const inv4 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  let issued4 = issueInvoice(inv4.value, ['INV-2025-0001', 'INV-2025-0002']).value;
  const totals4 = invoiceTotals(issued4);
  issued4 = recordPayment(issued4, {
    amount: totals4.total,
    date: '2025-10-10',
  }).value;

  const result = vatSummary([inv1.value, issued2, issued3, issued4]);

  // Only issued2, issued3, issued4 should contribute (inv1 is draft)
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 360000); // 3 invoices * 120000
  assert.equal(result[0].vat, 75600); // 3 invoices * 25200
});

