test('lateFee returns fee when 1 day overdue', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    terms: 'NET14',
  });

  const issued = issueInvoice(inv.value, []).value;
  const totals = invoiceTotals(issued);

  // Due 2025-10-21, asOf 2025-10-22 = 1 day overdue
  // fee = 145200 * 1 * 0.04 / 100 = 58.08 cents = 58 cents rounded
  const fee = lateFee(issued, '2025-10-22');

  assert(fee > 0);
  // LOGO-PACK 120000 + VAT 25200 = 145200
  // 1 day * 0.04% = 0.04% of 145200 = 58.08 → 58 cents
  assert.equal(fee, 58);
});

