    terms: 'NET14',
  });

  let issued = issueInvoice(inv.value, []).value;
  const totals = invoiceTotals(issued);

  // Pay half
  const paymentAmount = Math.floor(totals.total / 2);
  issued = recordPayment(issued, {
    amount: paymentAmount,
    date: '2025-10-20',
  }).value;

  // Due 2025-10-21, asOf 2025-10-22 = 1 day overdue
  // Remaining due ≈ 72600 (half of 145200)
  // fee = 72600 * 1 * 0.04 / 100 = 29.04 cents = 29 cents
  const fee = lateFee(issued, '2025-10-22');

  assert.equal(fee, 29);
});

